import { DuplicateAccountError } from "@/lib/errors";
import {
  hashPassword,
  hashToken,
  randomToken,
  verifyPassword,
} from "@/lib/hash";
import { RateLimitError, consumeRateLimit } from "@/lib/rate-limit";
import {
  InvalidSlugError,
  SLUG_MAX_LENGTH,
  SLUG_MIN_LENGTH,
  isReservedSlug,
  isValidSlug,
  slugify,
  uniqueSlug,
} from "@/lib/slug";
import { ORGANIZATION_NAME_MAX_LENGTH } from "@/schemas/organization";
import * as resetTokenRepo from "@/server/repositories/_password-reset-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as sessionRepo from "@/server/repositories/session-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { toIsoTimestamp } from "@/types/common";
import { createOrganization } from "./organization-service";
import { renderEmail, sendEmail } from "./email-service";
import { createSessionToken } from "./session-service";
import type {
  LoginInput,
  PasswordResetConfirmInput,
  PasswordResetRequestInput,
  RegisterInput,
} from "@/schemas/auth";
import type { OrgId, SessionId } from "@/types/common";
import type { User } from "@/types/member";
import type { Organization } from "@/types/organization";

/** Buckets guarding the unauthenticated endpoints. */
const LOGIN_BUCKET = "auth:login";
const REGISTER_BUCKET = "auth:register";
const RESET_BUCKET = "auth:password-reset";

/** Appended to the display name; the workspace name always ends with this. */
const WORKSPACE_NAME_SUFFIX = "'s workspace";

/** Used when a display name slugifies to nothing that can be a slug. */
const WORKSPACE_SLUG_FALLBACK = "workspace";

input.old_string:
export async function register(
  input: RegisterInput,
): Promise<{ user: User; org: Organization }> {
  const existing = await userRepo.findUserByEmail(input.email);
  if (existing) {
    throw new Error("An account with that email already exists");
  }

  const user = await userRepo.insertUser({
    email: input.email,
    name: input.name,
    passwordHash: await hashPassword(input.password),
  });

  // A reserved or awkward name is handled downstream: `createOrganization`
  // runs the slug through `uniqueSlug()`, which skips reserved words and
  // suffixes collisions.
  const org = await createOrganization(user.id, {
    name: `${input.name}'s workspace`,
    slug: slugify(input.name) || "workspace",
    plan: "free",
  });

  const welcome = await renderEmail("welcome", {
    orgName: org.name,
    recipientName: user.name,
  });
  await sendEmail({ to: user.email, ...welcome });

  return { user, org };
}

input.new_string:
export async function register(
  input: RegisterInput,
): Promise<{ user: User; org: Organization }> {
  const verdict = await consumeRateLimit(ANONYMOUS_ORG, REGISTER_BUCKET);
  if (!verdict.allowed) {
    throw new RateLimitError(REGISTER_BUCKET, verdict.resetAt);
  }

  const existing = await userRepo.findUserByEmail(input.email);
  if (existing) {
    throw new DuplicateAccountError();
  }

  let user: User;
  try {
    user = await userRepo.insertUser({
      email: input.email,
      name: input.name,
      passwordHash: await hashPassword(input.password),
    });
  } catch (error) {
    if (isDuplicateEmailConstraint(error)) throw new DuplicateAccountError();
    throw error;
  }

  const org = await createOrganization(user.id, {
    name: workspaceName(input.name),
    slug: await firstWorkspaceSlug(input.name),
    plan: "free",
  });

  const welcome = await renderEmail("welcome", {
    orgName: org.name,
    recipientName: user.name,
  });
  await sendEmail({ to: user.email, ...welcome });

  return { user, org };
}

/**
 * `<display name>'s workspace`, shortened from the front of the display name
 * until the whole string fits the organization name limit.
 */
function workspaceName(displayName: string): string {
  const room = ORGANIZATION_NAME_MAX_LENGTH - WORKSPACE_NAME_SUFFIX.length;
  const head =
    room > 0 && displayName.length > room
      ? displayName.slice(0, room).trimEnd()
      : displayName.trimEnd();
  return `${head}${WORKSPACE_NAME_SUFFIX}`;
}

/**
 * A slug `createOrganization` will accept. Reserved bases are suffixed the
 * way every other derived slug is; a base shorter than the minimum, or empty,
 * becomes `workspace` (also suffixed when that is taken).
 */
async function firstWorkspaceSlug(displayName: string): Promise<string> {
  const slugified = slugify(displayName);
  const base =
    slugified.length >= SLUG_MIN_LENGTH ? slugified : WORKSPACE_SLUG_FALLBACK;
  const primary = await allocateSlug(base);
  if (primary !== null) return primary;
  if (base !== WORKSPACE_SLUG_FALLBACK) {
    const fallback = await allocateSlug(WORKSPACE_SLUG_FALLBACK);
    if (fallback !== null) return fallback;
  }
  return emergencyWorkspaceSlug();
}

async function allocateSlug(base: string): Promise<string | null> {
  try {
    const taken = await orgRepo.listTakenOrgSlugs(base);
    const slug = uniqueSlug(base, taken);
    if (isValidSlug(slug) && !isReservedSlug(slug)) return slug;
    return null;
  } catch (error) {
    if (error instanceof InvalidSlugError) return null;
    throw error;
  }
}

function emergencyWorkspaceSlug(): string {
  const raw = `${WORKSPACE_SLUG_FALLBACK}-${Date.now().toString(36)}`;
  const slug = (
    raw.length <= SLUG_MAX_LENGTH ? raw : raw.slice(0, SLUG_MAX_LENGTH)
  ).replace(/-+$/g, "");
  return isValidSlug(slug) && !isReservedSlug(slug)
    ? slug
    : WORKSPACE_SLUG_FALLBACK;
}

function isDuplicateEmailConstraint(error: unknown): boolean {
  if (typeof error !== "object" || error === null) return false;
  const code = "code" in error ? String((error as { code: unknown }).code) : "";
  if (code !== "SQLITE_CONSTRAINT_UNIQUE" && code !== "SQLITE_CONSTRAINT") {
    return false;
  }
  const message = error instanceof Error ? error.message : "";
  return message.includes("users.email") || message.includes("users_email");
}

