import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { runMigrations } from "../private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/4cc25577-64f2-4d82-a637-9c838e85f0e9/src/server/db/migrate.ts";

const dir = mkdtempSync(join(tmpdir(), "signup-check-"));
const path = join(dir, "taskflow.db");
process.env.TASKFLOW_DB_PATH = path;
await runMigrations(path);

const { register, login, requestPasswordReset } = await import(
  "../private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/4cc25577-64f2-4d82-a637-9c838e85f0e9/src/server/services/auth-service.ts"
);
const { subscribe, resetEventBus } = await import(
  "../private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/4cc25577-64f2-4d82-a637-9c838e85f0e9/src/lib/event-bus.ts"
);
const { toAppError } = await import(
  "../private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/4cc25577-64f2-4d82-a637-9c838e85f0e9/src/lib/errors.ts"
);
const { resetRateLimits } = await import(
  "../private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/4cc25577-64f2-4d82-a637-9c838e85f0e9/src/lib/rate-limit.ts"
);
const { updateOrganizationSchema } = await import(
  "../private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/4cc25577-64f2-4d82-a637-9c838e85f0e9/src/schemas/organization.ts"
);
const { findSubscription } = await import(
  "../private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/4cc25577-64f2-4d82-a637-9c838e85f0e9/src/server/repositories/subscription-repository.ts"
);
const { getDb, users } = await import(
  "../private/var/folders/82/dclbn8z5181_3ppfdtp8csd40000gn/T/bench-scratch/4cc25577-64f2-4d82-a637-9c838e85f0e9/src/server/db/index.ts"
);
const { eq } = await import("drizzle-orm");

const password = "Correct1Horse2";

function input(name: string, email: string) {
  return {
    name,
    email,
    password,
    confirmPassword: password,
    acceptTerms: true as const,
  };
}

const failures: string[] = [];
function check(label: string, ok: boolean, detail?: unknown) {
  if (!ok) failures.push(`${label}: ${JSON.stringify(detail)}`);
  else console.log("ok", label);
}

resetEventBus?.();

let joins = 0;
subscribe("member.joined", () => {
  joins += 1;
});

const admin = await register(input("Admin", "Admin@Example.com"));
check("admin email stored lower", admin.user.email === "admin@example.com", admin.user.email);
check("admin slug not reserved", admin.org.slug !== "admin" && !admin.org.slug.startsWith("admin-") === false || admin.org.slug.startsWith("admin-"), admin.org.slug);
check("admin slug", admin.org.slug === "admin-2", admin.org.slug);
check("admin name", admin.org.name === "Admin's workspace", admin.org.name);
check("admin plan", admin.org.plan === "free", admin.org.plan);
check("admin trial null", admin.org.trialEndsAt === null, admin.org.trialEndsAt);
check("joins once so far", joins === 1, joins);
const sub = await findSubscription(admin.org.id);
check("sub active free", sub?.status === "active" && sub.plan === "free", sub);

const al = await register(input("Al", "al@example.com"));
check("al slug", al.org.slug === "al", al.org.slug);

const jay = await register(input("J", "j@example.com"));
check("j slug", jay.org.slug === "workspace", jay.org.slug);
check("j name", jay.org.name === "J's workspace", jay.org.name);

const yamada = await register(input("山田", "yamada@example.com"));
check("yamada slug", yamada.org.slug === "workspace-2", yamada.org.slug);

const billing = await register(input("Billing", "billing@example.com"));
check("billing slug", billing.org.slug === "billing-2", billing.org.slug);

const support = await register(input("Support", "support@example.com"));
check("support slug", support.org.slug === "support-2", support.org.slug);

const taskflow = await register(input("Taskflow", "taskflow@example.com"));
check("taskflow slug", taskflow.org.slug === "taskflow-2", taskflow.org.slug);

const longName = "A".repeat(80);
const long = await register(input(longName, "long@example.com"));
check("long ends with suffix", long.org.name.endsWith("'s workspace"), long.org.name);
check("long length", long.org.name.length <= 64, long.org.name.length);
check(
  "long schema",
  updateOrganizationSchema.safeParse({ orgId: long.org.id, name: long.org.name }).success,
  long.org.name.length,
);

const before = getDb().select().from(users).all().length;
let dupCode = "";
try {
  await register(input("Admin Two", "ADMIN@example.com"));
} catch (error) {
  dupCode = toAppError(error).code;
}
const after = getDb().select().from(users).all().length;
check("dup conflict", dupCode === "conflict", dupCode);
check("dup no row", before === after, { before, after });

const signedIn = await login({ email: "ADMIN@example.com", password, rememberMe: false });
check("login case", signedIn.user.email === "admin@example.com", signedIn.user.email);

await requestPasswordReset({ email: "ADMIN@example.com" });
check("reset lookup did not throw", true);

// second Al collides
const al2 = await register(input("Al", "al2@example.com"));
check("al suffix", al2.org.slug === "al-2", al2.org.slug);

// throttle
resetRateLimits();
let limited = false;
let created = 0;
for (let i = 0; i < 40; i += 1) {
  try {
    await register(input(`Person ${i}`, `p${i}@example.com`));
    created += 1;
  } catch (error) {
    const shape = toAppError(error);
    limited = shape.code === "rate_limited" && /wait/i.test(shape.message);
    check("limit message", limited, shape);
    break;
  }
}
check("eventually limited", limited, created);
check("not thousands", created < 40, created);

// login throttle via service
resetRateLimits();
let loginLimited = false;
for (let i = 0; i < 80; i += 1) {
  try {
    await login({ email: "missing@example.com", password: "nope", rememberMe: false });
  } catch (error) {
    const shape = toAppError(error);
    if (shape.code === "rate_limited") {
      loginLimited = /wait/i.test(shape.message);
      break;
    }
  }
}
check("login limited", loginLimited);

console.log(failures.length === 0 ? "ALL PASSED" : failures.join("\n"));
rmSync(dir, { recursive: true, force: true });
if (failures.length > 0) process.exit(1);

