const { resetRateLimits, RateLimitError } = await import("@/lib/rate-limit");
const { updateOrganizationSchema } = await import("@/schemas/organization");
const { findSubscription } = await import("@/server/repositories/subscription-repository");
const { getDb, users } = await import("@/server/db");

const password = "Correct1Horse2";

function input(name: string, email: string) {
  return {
    name,
    email,
    password,
    confirmPassword: password,
    acceptTerms: true as const,
  };
}

const failures: string[] = [];
function check(label: string, ok: boolean, detail?: unknown) {
  if (!ok) failures.push(`${label}: ${JSON.stringify(detail)}`);
  else console.log("ok", label, detail === undefined ? "" : JSON.stringify(detail));
}

let joins = 0;
subscribe("member.joined", () => {
  joins += 1;
});

const admin = await register(input("Admin", "Admin@Example.com"));
check("admin email", admin.user.email === "admin@example.com", admin.user.email);
check("admin slug", admin.org.slug === "admin-2", admin.org.slug);
check("admin name", admin.org.name === "Admin's workspace", admin.org.name);
check("admin plan", admin.org.plan === "free" && admin.org.trialEndsAt === null, admin.org);
const sub = await findSubscription(admin.org.id);
check("sub", sub?.status === "active" && sub.plan === "free", sub && { status: sub.status, plan: sub.plan });
check("joins", joins === 1, joins);

const al = await register(input("Al", "al@example.com"));
check("al slug", al.org.slug === "al", al.org.slug);

const jay = await register(input("J", "j@example.com"));
check("j slug", jay.org.slug === "workspace", jay.org.slug);
check("j name", jay.org.name === "J's workspace", jay.org.name);

const yamada = await register(input("山田", "yamada@example.com"));
check("yamada slug", yamada.org.slug === "workspace-2", yamada.org.slug);
check("yamada name", yamada.org.name === "山田's workspace", yamada.org.name);

for (const [name, email, slug] of [
  ["Billing", "billing@example.com", "billing-2"],
  ["Support", "support@example.com", "support-2"],
  ["Taskflow", "taskflow@example.com", "taskflow-2"],
] as const) {
  const org = await register(input(name, email));
  check(name, org.org.slug === slug, org.org.slug);
}

const longName = "A".repeat(80);
const long = await register(input(longName, "long@example.com"));
check("long suffix", long.org.name.endsWith("'s workspace"), long.org.name);
check("long len", long.org.name.length === 64, long.org.name.length);
check(
  "long schema",
  updateOrganizationSchema.safeParse({ orgId: long.org.id, name: long.org.name }).success,
);

const before = getDb().select().from(users).all().length;
let dup: unknown;
try {
  await register(input("Admin Two", "ADMIN@example.com"));
} catch (error) {
  dup = error;
}
const after = getDb().select().from(users).all().length;
check("dup class", dup instanceof DuplicateAccountError);
check("dup code", toAppError(dup).code === "conflict", toAppError(dup));
check("dup rows", before === after, { before, after });

const signedIn = await login({ email: "ADMIN@example.com", password, rememberMe: false });
check("login case", signedIn.user.email === "admin@example.com", signedIn.user.email);

await requestPasswordReset({ email: "ADMIN@example.com" });
check("reset request", true);

const al2 = await register(input("Al", "al2@example.com"));
check("al2", al2.org.slug === "al-2", al2.org.slug);

const punct = await register(input("!!!", "punct@example.com"));
check("punct", punct.org.slug === "workspace-3", punct.org.slug);

resetRateLimits();
let created = 0;
let limitedShape: { code: string; message: string } | null = null;
for (let i = 0; i < 40; i += 1) {
  try {
    await register(input(`Person ${i}`, `p${i}@example.com`));
    created += 1;
  } catch (error) {
    const shape = toAppError(error);
    limitedShape = { code: shape.code, message: shape.message };
    check("limit class", error instanceof RateLimitError);
    break;
  }
}
check("limited", limitedShape?.code === "rate_limited" && /wait/i.test(limitedShape.message), {
  created,
  limitedShape,
});

resetRateLimits();
let loginShape: { code: string; message: string } | null = null;
for (let i = 0; i < 80; i += 1) {
  try {
    await login({ email: "missing@example.com", password: "nope", rememberMe: false });
  } catch (error) {
    const shape = toAppError(error);
    if (shape.code === "rate_limited") {
      loginShape = { code: shape.code, message: shape.message };
      break;
    }
    if (shape.code !== "internal_error") {
      loginShape = { code: shape.code, message: shape.message };
      break;
    }
  }
}
check("login limited", loginShape?.code === "rate_limited" && /wait/i.test(loginShape.message ?? ""), loginShape);

resetRateLimits();
let resetSilent = true;
for (let i = 0; i < 20; i += 1) {
  try {
    await requestPasswordReset({ email: "nobody@example.com" });
  } catch {
    resetSilent = false;
  }
}
check("reset request stays silent", resetSilent);

let confirmShape: string | null = null;
for (let i = 0; i < 20; i += 1) {
  try {
    await confirmPasswordReset({
      token: "t".repeat(20),
      password,
      confirmPassword: password,
    });
  } catch (error) {
    const shape = toAppError(error);
    if (shape.code === "rate_limited") {
      confirmShape = shape.code;
      break;
    }
    confirmShape = shape.code;
  }
}
check("confirm limited", confirmShape === "rate_limited", confirmShape);

console.log(failures.length === 0 ? "ALL PASSED" : `FAILED\n${failures.join("\n")}`);
rmSync(dir, { recursive: true, force: true });
if (failures.length > 0) process.exit(1);

